<?php
require_once dirname(__DIR__).'/repositories/userPDO.php';
require_once dirname(__DIR__).'/repositories/studentPDO.php';
function userError($name,$email,$password=null) { $e=[]; if(mb_strlen($name)<2||mb_strlen($name)>120)$e[]='Name must be 2 to 120 characters.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>254)$e[]='Enter a valid email address.'; if($password!==null&&(strlen($password)<10||strlen($password)>128))$e[]='Password must be 10 to 128 characters.'; return $e; }
function registerUser($pdo,$input) { $name=trim((string)($input['full_name']??''));$email=strtolower(trim((string)($input['email']??'')));$password=(string)($input['password']??'');$confirm=(string)($input['confirm_password']??'');$role=(string)($input['role']??'');$e=userError($name,$email,$password);if($password!==$confirm)$e[]='Passwords do not match.';if(!in_array($role,['Student','Tutor'],true))$e[]='Select Student or Tutor.';if(findUserByEmail($pdo,$email))$e[]='An account already uses that email address.';if($e)throw new InvalidArgumentException(implode(' ',$e));return insertUser($pdo,$name,$email,password_hash($password,PASSWORD_DEFAULT),$role); }
function authenticateUser($pdo,$email,$password) { $u=findUserByEmail($pdo,$email);if(!$u||$u['status']!=='Active'||!password_verify($password,$u['password_hash']))return false;if(password_needs_rehash($u['password_hash'],PASSWORD_DEFAULT)){updateUserPassword($pdo,(int)$u['user_id'],password_hash($password,PASSWORD_DEFAULT));$u=findUserById($pdo,(int)$u['user_id']);}return $u; }
function saveOwnProfile($pdo,$id,$input) { $name=trim((string)($input['full_name']??''));$email=strtolower(trim((string)($input['email']??'')));$e=userError($name,$email);$found=findUserByEmail($pdo,$email);if($found&&(int)$found['user_id']!==$id)$e[]='An account already uses that email address.';if($e)throw new InvalidArgumentException(implode(' ',$e));$pdo->beginTransaction();try{updateOwnUser($pdo,$id,$name,$email);updateStudentForUser($pdo,$id,$name,$email);$pdo->commit();}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();throw $x;}return findUserById($pdo,$id); }
function changeOwnPassword($pdo,$id,$input) { $u=findUserById($pdo,$id);$current=(string)($input['current_password']??'');$new=(string)($input['new_password']??'');$confirm=(string)($input['confirm_password']??'');$e=[];if(!$u||!password_verify($current,$u['password_hash']))$e[]='Current password is incorrect.';if($new!==$confirm)$e[]='Passwords do not match.';$e=array_merge($e,userError('Valid Name','valid@example.edu',$new));if($e)throw new InvalidArgumentException(implode(' ',$e));return updateUserPassword($pdo,$id,password_hash($new,PASSWORD_DEFAULT)); }
function setManagedRole($pdo,$id,$role) { $u=findUserById($pdo,$id);if(!$u||!in_array($role,['Student','Tutor','Administrator'],true))throw new InvalidArgumentException('Invalid account or role.');if($u['role']==='Administrator'&&$u['status']==='Active'&&$role!=='Administrator'&&countActiveAdministrators($pdo)<=1)throw new DomainException('The last active administrator cannot be demoted.');return updateUserRole($pdo,$id,$role); }
function setManagedStatus($pdo,$id,$status) { $u=findUserById($pdo,$id);if(!$u||!in_array($status,['Active','Inactive'],true))throw new InvalidArgumentException('Invalid account or status.');if($u['role']==='Administrator'&&$u['status']==='Active'&&$status==='Inactive'&&countActiveAdministrators($pdo)<=1)throw new DomainException('The last active administrator cannot be deactivated.');return updateUserStatus($pdo,$id,$status); }
function removeManagedUser($pdo,$id) { $u=findUserById($pdo,$id);if(!$u)throw new InvalidArgumentException('Account not found.');if($u['role']==='Administrator'&&$u['status']==='Active'&&countActiveAdministrators($pdo)<=1)throw new DomainException('The last active administrator cannot be deleted.');if(userHasRelatedRecords($pdo,$id))throw new DomainException('Account deletion is blocked because related tutoring records are retained.');return deleteUserRow($pdo,$id); }
